def seg_int(p, a, b):
    # horizontal ray from p to +inf; count crossing of segment a-b (treat as open at one end)
    (px,py)=p; (x1,y1)=a; (x2,y2)=b
    if y1==y2: return 0
    if (y1>py)!=(y2>py):
        t=(py-y1)/(y2-y1)
        x=x1+t*(x2-x1)
        if x>px: return 1
    return 0
